# Sanity: no unused imports in the two touched modules
import ast, sys
for f in ("carbon_market/history_copy.py", "carbon_market/history_recovery.py"):
    tree = ast.parse(open(f).read())
    imported = []
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom):
            for a in node.names:
                imported.append(a.asname or a.name)
        elif isinstance(node, ast.Import):
            for a in node.names:
                imported.append((a.asname or a.name).split(".")[0])
    src = open(f).read()
    for name in imported:
        # count attribute/name uses beyond the import line
        used = src.count(name)
        print(f, name, "uses:", used)
